#include "estimated_taxes/tax_calculation.hpp"

#include <algorithm>
#include <limits>

namespace estimated_taxes {
namespace {
constexpr Cents kPpm = 1'000'000;
Cents add(Cents a, Cents b) { if ((b > 0 && a > std::numeric_limits<Cents>::max() - b) || (b < 0 && a < std::numeric_limits<Cents>::min() - b)) throw CalculationError("monetary calculation overflow"); return a + b; }
Cents subtract(Cents a, Cents b) { if (b == std::numeric_limits<Cents>::min()) throw CalculationError("monetary calculation overflow"); return add(a, -b); }
Cents multiply(Cents amount, int rate) { if (rate && (amount > std::numeric_limits<Cents>::max()/rate || amount < std::numeric_limits<Cents>::min()/rate)) throw CalculationError("monetary calculation overflow"); return amount * rate; }
Cents nonnegative_difference(Cents a, Cents b) { return a > b ? subtract(a,b) : 0; }
Cents bracket_tax_between(Cents start, Cents end, const std::vector<Bracket>& brackets) { Cents total{}; for (const auto& b: brackets) { const Cents lower=std::max(start,b.lower_bound_cents); const Cents upper=std::min(end,b.upper_bound_cents.value_or(end)); if(upper>lower) total=add(total,multiply_rate(subtract(upper,lower),b.rate_ppm)); } return total; }
TaxResult federal_result(const AnnualProjection& p,const Household& h,const RuleRevision& revision) { if(!revision.federal) throw CalculationError("active federal rule revision is invalid"); const auto& r=*revision.federal; validate(r); TaxResult out; out.rule_revision_id=revision.id; out.capital_netting=net_capital_gains(p.investments.short_term_gain_cents,p.investments.long_term_gain_cents,r.capital_loss_limit_cents); auto& d=out.details; d.supported_agi_cents=add(add(add(p.federal_wages.projected_annual_cents,p.investments.ordinary_dividends_cents),out.capital_netting.ordinary_gain_cents),out.capital_netting.preferential_gain_cents); d.supported_agi_cents=subtract(d.supported_agi_cents,out.capital_netting.deductible_loss_cents); d.deduction_cents=add(r.standard_deduction_cents, multiply(r.age_or_blind_addition_cents,(h.spouse_1.age_65_or_older?1:0)+(h.spouse_2.age_65_or_older?1:0)+(h.spouse_1.blind?1:0)+(h.spouse_2.blind?1:0))); d.taxable_income_cents=nonnegative_difference(d.supported_agi_cents,d.deduction_cents); d.preferential_pool_cents=std::min(d.taxable_income_cents,add(p.investments.qualified_dividends_cents,out.capital_netting.preferential_gain_cents)); d.ordinary_taxable_income_cents=subtract(d.taxable_income_cents,d.preferential_pool_cents); d.ordinary_tax_cents=progressive_tax(d.ordinary_taxable_income_cents,r.ordinary_brackets); d.preferential_tax_cents=bracket_tax_between(d.ordinary_taxable_income_cents,d.taxable_income_cents,r.preferential_brackets); d.ordinary_tax_on_all_income_cents=progressive_tax(d.taxable_income_cents,r.ordinary_brackets); d.regular_tax_cents=std::min(d.ordinary_tax_on_all_income_cents,add(d.ordinary_tax_cents,d.preferential_tax_cents)); const Cents nii=std::max<Cents>(0,subtract(add(add(p.investments.ordinary_dividends_cents,out.capital_netting.ordinary_gain_cents),out.capital_netting.preferential_gain_cents),out.capital_netting.deductible_loss_cents)); d.niit_cents=multiply_rate(std::min(nii,nonnegative_difference(d.supported_agi_cents,r.niit_threshold_cents)),r.niit_rate_ppm); d.additional_medicare_cents=multiply_rate(nonnegative_difference(p.federal_wages.projected_annual_cents,r.additional_medicare_threshold_cents),r.additional_medicare_rate_ppm); d.annual_liability_cents=add(add(d.regular_tax_cents,d.niit_cents),d.additional_medicare_cents); d.projected_withholding_cents=add(p.federal_withholding.projected_annual_cents,p.investments.federal_withholding_cents); d.amount_requiring_estimated_payments_cents=nonnegative_difference(d.annual_liability_cents,d.projected_withholding_cents); out.effective_rate_ppm=d.supported_agi_cents==0?0:static_cast<int>(multiply(d.annual_liability_cents,kPpm)/d.supported_agi_cents); out.warnings.push_back({WarningSeverity::caution,"additional_medicare_approximation","federal","Additional Medicare Tax is estimated from federal taxable wages."});out.warnings.push_back({WarningSeverity::caution,"niit_adjustments_omitted","federal","NIIT omits investment expenses and Form 8960 adjustments."});out.warnings.push_back({WarningSeverity::caution,"amt_not_calculated","federal","Alternative minimum tax is not calculated."});out.warnings.push_back({WarningSeverity::caution,"federal_credits_omitted","federal","Federal credits and itemized deductions are not calculated."});if(out.capital_netting.unused_loss_cents>0)out.warnings.push_back({WarningSeverity::caution,"unused_capital_loss","federal","Capital loss above the annual limit is not carried forward."});if(revision.modified)out.warnings.push_back({WarningSeverity::caution,"custom_tax_rules","federal","Custom federal tax rules are active."}); return out; }
TaxResult california_result(const AnnualProjection& p,const RuleRevision& revision) { if(!revision.california) throw CalculationError("active California rule revision is invalid"); const auto& r=*revision.california; validate(r); TaxResult out;out.rule_revision_id=revision.id;out.capital_netting=net_capital_gains(p.investments.short_term_gain_cents,p.investments.long_term_gain_cents,r.capital_loss_limit_cents);auto& d=out.details; d.supported_agi_cents=add(add(add(p.california_wages.projected_annual_cents,p.investments.ordinary_dividends_cents),out.capital_netting.ordinary_gain_cents),out.capital_netting.preferential_gain_cents);d.supported_agi_cents=subtract(d.supported_agi_cents,out.capital_netting.deductible_loss_cents);d.deduction_cents=r.standard_deduction_cents;d.taxable_income_cents=nonnegative_difference(d.supported_agi_cents,d.deduction_cents);d.ordinary_tax_cents=progressive_tax(d.taxable_income_cents,r.ordinary_brackets);d.tax_before_exemption_cents=d.ordinary_tax_cents;d.exemption_credit_cents=r.joint_personal_exemption_credit_cents;d.tax_after_exemption_cents=nonnegative_difference(d.tax_before_exemption_cents,d.exemption_credit_cents);d.regular_tax_cents=d.tax_after_exemption_cents;d.behavioral_health_services_cents=multiply_rate(nonnegative_difference(d.taxable_income_cents,r.behavioral_health_services_threshold_cents),r.behavioral_health_services_rate_ppm);d.annual_liability_cents=add(d.regular_tax_cents,d.behavioral_health_services_cents);d.projected_withholding_cents=add(p.california_withholding.projected_annual_cents,p.investments.california_withholding_cents);d.amount_requiring_estimated_payments_cents=nonnegative_difference(d.annual_liability_cents,d.projected_withholding_cents);out.effective_rate_ppm=d.supported_agi_cents==0?0:static_cast<int>(multiply(d.annual_liability_cents,kPpm)/d.supported_agi_cents);out.warnings.push_back({WarningSeverity::caution,"california_exemption_credit_limitation_omitted","california","California exemption-credit AGI limitation is not calculated."});if(out.capital_netting.unused_loss_cents>0)out.warnings.push_back({WarningSeverity::caution,"unused_capital_loss","california","Capital loss above the annual limit is not carried forward."});if(revision.modified)out.warnings.push_back({WarningSeverity::caution,"custom_tax_rules","california","Custom California tax rules are active."});return out; }
}
Cents multiply_rate(Cents amount,int rate_ppm) { if(rate_ppm<0||rate_ppm>kPpm)throw CalculationError("invalid rate"); const Cents product=multiply(amount,rate_ppm); const Cents adjustment=product>=0?kPpm/2:-(kPpm/2); return subtract(add(product,adjustment),0)/kPpm; }
Cents progressive_tax(Cents income,const std::vector<Bracket>& b) { if(income<0)throw CalculationError("taxable income cannot be negative"); Cents total{};for(const auto& x:b){if(income<=x.lower_bound_cents)continue;const Cents end=std::min(income,x.upper_bound_cents.value_or(income));total=add(total,multiply_rate(subtract(end,x.lower_bound_cents),x.rate_ppm));}return total; }
CapitalNetting net_capital_gains(Cents s,Cents l,Cents limit) { if(limit<0)throw CalculationError("capital loss limit cannot be negative");CapitalNetting r;const Cents net=add(s,l);if(s>=0&&l>=0){r.ordinary_gain_cents=s;r.preferential_gain_cents=l;}else if(net>=0){if(s>=0)r.ordinary_gain_cents=net;else r.preferential_gain_cents=net;}else { const Cents loss=subtract(0,net);r.deductible_loss_cents=std::min(loss,limit);r.unused_loss_cents=subtract(loss,r.deductible_loss_cents);}return r; }
TaxCalculation calculate_tax(const AnnualProjection& p,const Household& h,const ActiveRules& r) { return {federal_result(p,h,r.federal),california_result(p,r.california)}; }
}  // namespace estimated_taxes
